        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs\nYogurt\nGaram masala\nTomato sauce\nHeavy cream\nGinger\nGarlic\nOnion", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, ginger, and garlic.\n4. Add tomato sauce and simmer.\n5. Add cream and garam masala.\n6. Add chicken pieces and simmer 10 minutes." },
        new Recipe { Id = 4, Title = "Vegetable Pad Thai", Category = "Thai", Ingredients = "Rice noodles\nTofu\nBean sprouts\nPeanuts\nLime\nTamarind paste\nFish sauce\nEggs\nGreen onions", Steps = "1. Soak rice noodles in warm water 30 minutes.\n2. Press and cube tofu, then pan-fry until golden.\n3. Scramble eggs in the same pan.\n4. Add noodles and sauce (tamarind, fish sauce, sugar).\n5. Toss with bean sprouts and green onions.\n6. Serve with crushed peanuts and lime wedge." },
