        new Recipe { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt", Steps = "1. Halve and pit avocados.\n2. Mash in a bowl to desired consistency.\n3. Dice onion, jalapeño, tomato, and cilantro.\n4. Fold vegetables into avocado.\n5. Add lime juice and salt to taste.\n6. Serve immediately with tortilla chips." },
        new Recipe { Id = 7, Title = "Green Curry", Category = "Thai", Ingredients = "Coconut milk\nGreen curry paste\nChicken or tofu\nBamboo shoots\nThai basil\nFish sauce\nPalm sugar", Steps = "1. Heat coconut cream in a wok until it splits.\n2. Fry curry paste in the cream for 2 minutes.\n3. Add protein and cook through.\n4. Pour in remaining coconut milk.\n5. Add bamboo shoots, fish sauce, and sugar.\n6. Finish with Thai basil leaves." },
        new Recipe { Id = 8, Title = "Dal Tadka", Category = "Indian", Ingredients = "Yellow lentils\nTurmeric\nCumin seeds\nGhee\nGarlic\nDried red chilies\nTomato\nCilantro", Steps = "1. Wash lentils and pressure cook with turmeric.\n2. Mash cooked lentils to a smooth consistency.\n3. Heat ghee in a small pan.\n4. Add cumin seeds, garlic, and dried chilies.\n5. Pour the tadka over the dal.\n6. Garnish with cilantro and serve with rice." },
    };

    public static IReadOnlyList<Recipe> GetAll() => _recipes.AsReadOnly();

    public static IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public static Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public static IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().ToList();

    public static void Add(Recipe recipe)
    {
        recipe.Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
        _recipes.Add(recipe);
    }

    public static void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            recipe.TotalRatingPoints += stars;
            recipe.RatingCount++;
        }
    }
}
